const KEY='molkky-score-v2';
const state=load()||{screen:'setup',savedNames:[],players:['',''],teams:false,order:'entry',sort:'turn',game:null,modal:null,profile:null,knownRecent:false,knownDelete:false};
const APP_SCHEMA=3;
try{state.savedNames=Array.isArray(state.savedNames)?state.savedNames:[];state.players=Array.isArray(state.players)&&state.players.length>=2?state.players:['',''];state.modal=null;state.profile=null;if(state.game){const g=state.game;if(!Array.isArray(g.players)||!g.players.length)throw new Error('Partie invalide');g.actions=Array.isArray(g.actions)?g.actions:[];g.pending=g.pending??null;g.round=Number.isFinite(g.round)?g.round:1;g.current=Number.isFinite(g.current)?g.current:0;g.players.forEach(p=>{p.score=Number.isFinite(p.score)?p.score:0;p.misses=Number.isFinite(p.misses)?p.misses:0;p.throws=Array.isArray(p.throws)?p.throws:[];p.eliminated=!!p.eliminated;p.finished=!!p.finished});if(state.teams){g.teamOrders=Array.isArray(g.teamOrders)?g.teamOrders:g.players.map(p=>p.members?.map((_,i)=>i)||[0]);g.teamUsed=Array.isArray(g.teamUsed)?g.teamUsed:g.players.map(p=>p.members?.map(()=>false)||[false]);g.teamCycle=Array.isArray(g.teamCycle)?g.teamCycle:g.players.map(()=>0);g.completedCycles=Array.isArray(g.completedCycles)?g.completedCycles:g.players.map(()=>0);g.currentMember=Number.isFinite(g.currentMember)?g.currentMember:0;g.awaitingMember=!!g.awaitingMember}}state.schemaVersion=APP_SCHEMA}catch{state.screen='setup';state.game=null;state.modal=null;state.profile=null;state.schemaVersion=APP_SCHEMA}
function load(){try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){save();document.querySelector('#app').innerHTML=`<div class="app">${state.screen==='setup'?setupView():gameView()}${state.modal?modalView():''}${state.profile!==null?profileView():''}</div>`;bind()}
function setupView(){const known=[...state.savedNames].sort((a,b)=>state.knownRecent?(b.used||0)-(a.used||0):a.name.localeCompare(b.name,'fr'));return `<section class="hero"><small>NOUVELLE PARTIE</small><h1>Mölkky Score</h1></section><section class="card"><img class="placement-home" src="placement-quilles.png" alt="Placement initial des douze quilles"><h2>Qui joue ?</h2><div class="count-buttons">${Array.from({length:17},(_,i)=>i+2).map(n=>`<button data-count="${n}" class="${state.players.length===n?'active':''}">${n}</button>`).join('')}</div><div class="name-grid">${state.players.map((p,i)=>`<input data-player="${i}" value="${esc(p)}" placeholder="Joueur ${i+1}" aria-label="Nom du joueur ${i+1}">`).join('')}</div>${known.length?`<div class="known-head"><strong>Joueurs connus</strong><div class="mini-tools"><button id="knownSort">${state.knownRecent?'Récent':'A–Z'}</button><button id="knownDelete" class="${state.knownDelete?'active':''}">🗑</button></div></div><div class="known-list">${known.map(n=>`<button data-known="${esc(n.name)}" class="${state.players.includes(n.name)?'used':''}">${state.knownDelete?'× ':''}${esc(n.name)}</button>`).join('')}</div>`:''}<div class="segments">${[['entry','Saisie'],['alpha','A–Z'],['random','Aléatoire']].map(([v,l])=>`<button data-order="${v}" class="${state.order===v?'active':''}">${l}</button>`).join('')}</div><label class="row team-box"><input id="teams" type="checkbox" ${state.teams?'checked':''}><strong>Jouer en équipes</strong></label><div id="error"></div><button class="btn orange validate" id="start">COMMENCER LA PARTIE</button></section>`}
function gameView(){const g=state.game,p=g.players[g.current];return `<section class="hero"><small>MANCHE ${g.round} · JOUEUR ${g.current+1}/${g.players.length}${g.correction?' · MODIFICATION':''}</small><h1>À toi, ${esc(p.name)} !</h1></section><section class="card"><div class="score-head"><div><span class="muted">SCORE ACTUEL</span><div class="bigscore">${p.score}</div></div><div class="misses">${missIcons(p.misses)}</div></div></section><h3>Combien de points ?</h3><div class="score-grid">${Array.from({length:12},(_,i)=>`<button data-score="${i+1}" class="${g.pending===i+1?'selected':''}">${i+1}</button>`).join('')}</div><button class="btn orange validate" id="validate">${g.pending?`VALIDER ${g.pending} POINT${g.pending>1?'S':''}`:'VALIDER 0'}</button><div class="game-tools"><button class="btn ghost icon-only" id="undo" ${!g.actions.length||g.correction?'disabled':''} aria-label="Modifier le dernier lancer">↶</button>${g.correction?'<button class="btn ghost icon-only" id="resume" aria-label="Revenir">↷</button>':''}<span class="tool-spacer"></span><button class="btn ghost" id="quit">Terminer</button></div><div class="ranking-title"><h3 aria-label="Joueurs">♟</h3><select id="sort"><option value="turn" ${state.sort==='turn'?'selected':''}>Tour</option><option value="score" ${state.sort==='score'?'selected':''}>Score</option><option value="alpha" ${state.sort==='alpha'?'selected':''}>A–Z</option></select></div>${rankingRows(false)}`}
function missIcons(n){return `<span aria-label="${n} échec${n>1?'s':''}">${'×'.repeat(n)}${'○'.repeat(3-n)}</span>`}
function ordered(final=false){const a=state.game.players.map((p,i)=>({...p,i}));if(final||state.sort==='score')a.sort((x,y)=>y.score-x.score||x.i-y.i);else if(state.sort==='alpha')a.sort((x,y)=>x.name.localeCompare(y.name,'fr'));return a}
function trophy(rank){return rank<3?`<span class="trophy t${rank+1}">🏆</span>`:''}
function rankingRows(final){const list=ordered(final),showPodium=final||state.game.players.some(p=>p.finished);return list.map((p,rank)=>`<button class="player-row ${p.i===state.game.current&&!final?'current':''} ${p.eliminated?'eliminated':''} ${p.finished?'finished':''}" data-profile="${p.i}"><span class="turn-rank">${p.i+1}</span>${showPodium?trophy(rank):''}<strong class="row-name">${esc(p.name)}</strong><span class="row-misses">${missIcons(p.misses)}</span><strong>${p.score} pts</strong></button>`).join('')}
function stats(p){const vals=p.throws.map(t=>t.points),ok=vals.filter(v=>v>0);return{avg:ok.length?(ok.reduce((a,b)=>a+b,0)/ok.length).toFixed(1):'—',best:ok.length?Math.max(...ok):'—',fails:vals.filter(v=>v===0).length,overs:p.throws.filter(t=>t.overflow).length}}
function profileView(){const p=state.game.players[state.profile],s=stats(p);return `<div class="overlay profile-overlay"><section class="sheet"><header><div><small>FICHE DU JOUEUR</small><h2>${esc(p.name)}</h2></div><button class="icon-btn close-profile">×</button></header><div class="stat-grid"><div class="stat"><span>Score</span><b>${p.score}</b></div><div class="stat"><span>Moyenne</span><b>${s.avg}</b></div><div class="stat"><span>Meilleur lancer</span><b>${s.best}</b></div><div class="stat"><span>Échecs</span><b>${s.fails}</b></div><div class="stat"><span>Lancers</span><b>${p.throws.length}</b></div><div class="stat"><span>Retours à 25</span><b>${s.overs}</b></div></div><h3>Historique</h3>${p.throws.length?`<ol class="throws">${p.throws.map(t=>`<li><span>Manche ${t.round}</span><b>${t.points||'0'}</b><span>${t.after} pts</span></li>`).join('')}</ol>`:'<div class="empty">Aucun lancer.</div>'}</section></div>`}
function modalView(){const m=state.modal;if(m.type==='winner')return `<div class="overlay"><section class="sheet winner"><div class="trophy-big">🏆</div><h2>${esc(m.name)} gagne !</h2><button class="btn orange" id="continue">Continuer avec les autres</button><button class="btn ghost" id="finish">Voir le classement final</button></section></div>`;return `<div class="overlay"><section class="sheet final-sheet"><h2>Partie terminée</h2>${rankingRows(true)}<div class="final-actions"><button class="btn ghost" id="cancelFinal">Annuler</button><button class="btn orange" id="newgame">Nouvelle partie</button></div></section></div>`}
function bind(){document.querySelectorAll('[data-player]').forEach(x=>x.oninput=e=>{state.players[+e.target.dataset.player]=e.target.value;save()});document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{const n=+b.dataset.count;while(state.players.length<n)state.players.push('');state.players.length=n;render()});document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{state.order=b.dataset.order;render()});document.querySelector('#teams')?.addEventListener('change',e=>{state.teams=e.target.checked;render()});document.querySelector('#knownSort')?.addEventListener('click',()=>{state.knownRecent=!state.knownRecent;render()});document.querySelector('#knownDelete')?.addEventListener('click',()=>{state.knownDelete=!state.knownDelete;render()});document.querySelectorAll('[data-known]').forEach(b=>b.onclick=()=>knownClick(b.dataset.known));document.querySelector('#start')?.addEventListener('click',startGame);document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>{state.game.pending=state.game.pending===+b.dataset.score?null:+b.dataset.score;render()});document.querySelector('#validate')?.addEventListener('click',commitThrow);document.querySelector('#undo')?.addEventListener('click',beginCorrection);document.querySelector('#resume')?.addEventListener('click',cancelCorrection);document.querySelector('#quit')?.addEventListener('click',()=>{state.modal={type:'final'};render()});document.querySelector('#sort')?.addEventListener('change',e=>{state.sort=e.target.value;render()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.profile=+b.dataset.profile;render()});document.querySelector('.close-profile')?.addEventListener('click',closeProfile);document.querySelector('.profile-overlay')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closeProfile()});document.querySelector('#continue')?.addEventListener('click',continueAfterWin);document.querySelector('#finish')?.addEventListener('click',()=>{state.game.players.find(p=>p.name===state.modal.name).finished=true;state.modal={type:'final'};render()});document.querySelector('#cancelFinal')?.addEventListener('click',()=>{state.modal=null;render()});document.querySelector('#newgame')?.addEventListener('click',()=>{state.screen='setup';state.game=null;state.modal=null;state.profile=null;render()})}
function closeProfile(){state.profile=null;render()}
function knownClick(name){if(state.knownDelete){if(confirm(`Supprimer ${name} de l’historique ?`))state.savedNames=state.savedNames.filter(n=>n.name!==name)}else{const at=state.players.indexOf(name);if(at>=0)state.players[at]='';else{const empty=state.players.findIndex(n=>!n.trim());if(empty>=0)state.players[empty]=name}}render()}
function startGame(){let names=state.players.map(x=>x.trim()).filter(Boolean),err=document.querySelector('#error');if(names.length<2){err.innerHTML='<div class="notice">Il faut au moins deux joueurs.</div>';return}if(new Set(names.map(n=>n.toLowerCase())).size!==names.length){err.innerHTML='<div class="notice">Deux noms sont identiques.</div>';return}if(state.teams){err.innerHTML='<div class="notice">La configuration détaillée des équipes reste à terminer.</div>';return}if(state.order==='alpha')names.sort((a,b)=>a.localeCompare(b,'fr'));if(state.order==='random')names.sort(()=>Math.random()-.5);const now=Date.now();names.forEach(name=>{const x=state.savedNames.find(n=>n.name.toLowerCase()===name.toLowerCase());x?x.used=now:state.savedNames.push({name,used:now})});state.game={players:names.map(name=>({name,score:0,misses:0,eliminated:false,finished:false,throws:[]})),current:0,round:1,pending:null,actions:[],correction:null};state.screen='game';render()}
function applyResult(p,points,round){let overflow=false;if(points===0){p.misses++;if(p.misses>=3)p.eliminated=true}else{p.misses=0;p.score+=points;if(p.score>50){p.score=25;overflow=true}}p.throws.push({round,points,after:p.score,overflow});return overflow}
function commitThrow(){const g=state.game,p=g.players[g.current],points=g.pending||0;if(g.correction){const a=g.actions[g.correction.index];p.score=a.before.score;p.misses=a.before.misses;p.eliminated=a.before.eliminated;p.finished=a.before.finished;p.throws.pop();applyResult(p,points,a.round);a.points=points;g.current=g.correction.resumeCurrent;g.round=g.correction.resumeRound;g.correction=null;g.pending=null;if(p.score===50)state.modal={type:'winner',name:p.name};render();return}const before={score:p.score,misses:p.misses,eliminated:p.eliminated,finished:p.finished};applyResult(p,points,g.round);g.actions.push({player:g.current,round:g.round,points,before});g.pending=null;if(p.score===50){state.modal={type:'winner',name:p.name};render();return}advance();render()}
function beginCorrection(){const g=state.game,a=g.actions.at(-1);if(!a)return;g.correction={index:g.actions.length-1,resumeCurrent:g.current,resumeRound:g.round};g.current=a.player;g.round=a.round;g.pending=a.points||null;render()}
function cancelCorrection(){const g=state.game,c=g.correction;if(!c)return;g.current=c.resumeCurrent;g.round=c.resumeRound;g.pending=null;g.correction=null;render()}
function continueAfterWin(){const p=state.game.players.find(p=>p.name===state.modal.name);p.finished=true;state.game.continueMode=true;state.modal=null;advance();render()}
function advance(){const g=state.game,active=g.players.filter(p=>!p.eliminated&&!p.finished).length;if(active===0||(!g.continueMode&&active<=1)){state.modal={type:'final'};return}let n=g.current;do{n=(n+1)%g.players.length;if(n===0)g.round++}while(g.players[n].eliminated||g.players[n].finished);g.current=n}
const COLORS=['#dcebd5','#d6e7f5','#f7dfc8','#eadcf2','#f5d6d6','#d8eee9'];
state.target=state.target||50;state.eliminations=state.eliminations!==false;state.teamCount=state.teamCount||2;state.teamAssignments=state.teamAssignments||state.players.map((_,i)=>i%2);state.bestOf3=!!state.bestOf3;
missIcons=function(n){return `<span aria-label="${n} échec${n>1?'s':''}">${Array.from({length:n},()=>'<i>×</i>').join('')}</span>`};
setupView=function(){const known=[...state.savedNames].sort((a,b)=>state.knownRecent?(b.used||0)-(a.used||0):a.name.localeCompare(b.name,'fr'));return `<section class="hero"><small>NOUVELLE PARTIE</small><h1>Mölkky Score</h1></section><section class="card"><img class="placement-home" src="placement-quilles.png" alt="Placement initial des douze quilles"><h2>Qui joue ?</h2><div class="count-buttons">${Array.from({length:17},(_,i)=>i+2).map(n=>`<button data-count="${n}" class="${state.players.length===n?'active':''}">${n}</button>`).join('')}</div><div class="name-grid">${state.players.map((p,i)=>`<input data-player="${i}" value="${esc(p)}" placeholder="Joueur ${i+1}">`).join('')}</div>${known.length?`<div class="known-head"><strong>Joueurs connus</strong><div class="mini-tools"><button id="knownSort">${state.knownRecent?'Récent':'A–Z'}</button><button id="knownDelete" class="${state.knownDelete?'active':''}">🗑</button></div></div><div class="known-list">${known.map(n=>`<button data-known="${esc(n.name)}" class="${state.players.includes(n.name)?'used':''}">${state.knownDelete?'× ':''}${esc(n.name)}</button>`).join('')}</div>`:''}<div class="segments">${[['entry','Saisie'],['alpha','A–Z'],['random','Aléatoire']].map(([v,l])=>`<button data-order="${v}" class="${state.order===v?'active':''}">${l}</button>`).join('')}</div><div class="option-grid"><div class="option-box"><label>Éliminations</label><select id="eliminations"><option value="yes" ${state.eliminations?'selected':''}>Oui</option><option value="no" ${!state.eliminations?'selected':''}>Non · retour à 0</option></select></div><div class="option-box"><label>Score à atteindre</label><select id="target">${[50,75,100,125,150,175,200].map(v=>`<option ${state.target===v?'selected':''}>${v}</option>`).join('')}</select></div></div><label class="row team-box"><input id="teams" type="checkbox" ${state.teams?'checked':''}><strong>Jouer en équipes</strong></label>${state.teams?teamSetup():''}<div id="error"></div><button class="btn orange validate" id="start">COMMENCER LA PARTIE</button></section>`};
function teamSetup(){return `<div class="team-config"><label>Nombre d’équipes <select id="teamCount">${[2,3,4,5,6].map(n=>`<option ${state.teamCount===n?'selected':''}>${n}</option>`).join('')}</select></label>${state.players.map((p,i)=>`<div class="team-assign"><span>${esc(p||`Joueur ${i+1}`)}</span><select data-team="${i}">${Array.from({length:state.teamCount},(_,t)=>`<option value="${t}" ${state.teamAssignments[i]===t?'selected':''}>Équipe ${t+1}</option>`).join('')}</select></div>`).join('')}${state.teamCount===2?`<label><input id="bestOf3" type="checkbox" ${state.bestOf3?'checked':''}> Deux manches gagnantes</label>`:''}</div>`}
gameView=function(){const g=state.game,p=g.players[g.current],member=p.members?.[g.currentMember]||p.name;return `<section class="hero"><small>TOUR ${g.round} · ${g.slot+1}/${g.schedule.length}${g.correction?' · MODIFICATION':''}</small><h1>À toi, ${esc(member)} !</h1>${p.members?`<div>${esc(p.name)} · ${p.score}/${state.target}</div>`:''}</section><section class="card"><div class="score-head"><div><span class="muted">SCORE ACTUEL</span><div class="bigscore">${p.score}</div></div><div class="misses">${missIcons(p.misses)}</div></div></section><h3>Combien de points ?</h3><div class="score-grid">${Array.from({length:12},(_,i)=>`<button data-score="${i+1}" class="${g.pending===i+1?'selected':''}">${i+1}</button>`).join('')}</div><button class="btn orange validate" id="validate">${g.pending?`VALIDER ${g.pending} POINT${g.pending>1?'S':''}`:'VALIDER 0'}</button><div class="game-tools"><button class="btn ghost icon-only" id="undo" ${!g.actions.length||g.correction?'disabled':''}>↶</button>${g.correction?'<button class="btn ghost icon-only" id="resume">↷</button>':''}<span class="tool-spacer"></span><button class="btn ghost" id="quit">Terminer</button></div><div class="ranking-title"><h3 aria-label="Participants">👥</h3><div class="sort-radios"><button data-sort="turn" class="${state.sort==='turn'?'active':''}">↻</button><button data-sort="alpha" class="${state.sort==='alpha'?'active':''}">AZ</button><button data-sort="score" class="${state.sort==='score'?'active':''}">🏆</button></div></div>${rankingRows(false)}`};
rankingRows=function(final){const list=ordered(final),podium=final||state.game.players.some(p=>p.finished);return list.map((p,rank)=>`<button style="background:${p.color||''}" class="player-row ${p.i===state.game.current&&!final?'current':''} ${p.eliminated?'eliminated':''} ${p.finished?'finished':''}" data-profile="${p.i}"><span class="turn-rank">${p.i+1}</span>${podium?trophy(rank):'<span></span>'}<strong class="row-name">${esc(p.name)}${p.members?`<small>${p.members.map(esc).join(' · ')}</small>`:''}</strong><strong>${p.score} pts${p.wins?` · ${p.wins} M`:''}</strong><span class="row-misses">${missIcons(p.misses)}</span></button>`).join('')};
const priorBind=bind;bind=function(){priorBind();document.querySelector('#eliminations')?.addEventListener('change',e=>{state.eliminations=e.target.value==='yes';render()});document.querySelector('#target')?.addEventListener('change',e=>{state.target=+e.target.value;render()});document.querySelector('#teamCount')?.addEventListener('change',e=>{state.teamCount=+e.target.value;state.teamAssignments=state.players.map((_,i)=>i%state.teamCount);render()});document.querySelectorAll('[data-team]').forEach(s=>s.onchange=e=>{state.teamAssignments[+e.target.dataset.team]=+e.target.value;save()});document.querySelector('#bestOf3')?.addEventListener('change',e=>{state.bestOf3=e.target.checked;save()});document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{state.sort=b.dataset.sort;render()})};
startGame=function(){const entries=state.players.map((name,i)=>({name:name.trim(),team:state.teamAssignments[i]??i%state.teamCount})).filter(x=>x.name),err=document.querySelector('#error');if(entries.length<2){err.innerHTML='<div class="notice">Il faut au moins deux joueurs.</div>';return}if(new Set(entries.map(x=>x.name.toLowerCase())).size!==entries.length){err.innerHTML='<div class="notice">Deux noms sont identiques.</div>';return}let ps;if(state.teams){const groups=Array.from({length:state.teamCount},(_,t)=>entries.filter(x=>x.team===t).map(x=>x.name));if(groups.some(g=>!g.length)){err.innerHTML='<div class="notice">Chaque équipe doit contenir un joueur.</div>';return}ps=groups.map((members,i)=>({name:`Équipe ${i+1}`,members,color:COLORS[i%COLORS.length],score:0,misses:0,eliminated:false,finished:false,throws:[],wins:0,total:0}))}else{let names=entries.map(x=>x.name);if(state.order==='alpha')names.sort((a,b)=>a.localeCompare(b,'fr'));if(state.order==='random')names.sort(()=>Math.random()-.5);ps=names.map(name=>({name,score:0,misses:0,eliminated:false,finished:false,throws:[]}))}const now=Date.now();entries.forEach(({name})=>{const x=state.savedNames.find(n=>n.name.toLowerCase()===name.toLowerCase());x?x.used=now:state.savedNames.push({name,used:now})});state.game={players:ps,current:0,currentMember:0,slot:0,schedule:makeSchedule(ps,0),round:1,pending:null,actions:[],correction:null,continueMode:false,matchRound:1};setFromSlot();state.screen='game';render()};
function makeSchedule(ps,start){const out=[],max=Math.max(...ps.map(p=>p.members?.length||1));for(let m=0;m<max;m++)for(let k=0;k<ps.length;k++){const i=(start+k)%ps.length,n=ps[i].members?.length||1;if(m<n)out.push({team:i,member:m})}return out}
function setFromSlot(){const g=state.game,x=g.schedule[g.slot];g.current=x.team;g.currentMember=x.member}
applyResult=function(p,points,round){let overflow=false;if(points===0){p.misses++;if(p.misses>=3){if(state.eliminations)p.eliminated=true;else{p.score=0;p.misses=0}}}else{p.misses=0;p.score+=points;if(p.score>state.target){p.score=Math.floor(state.target/2);overflow=true}}p.throws.push({round,points,after:p.score,overflow});return overflow};
advance=function(){const g=state.game,active=g.players.filter(p=>!p.eliminated&&!p.finished).length;if(active===0||(!g.continueMode&&active<=1)){state.modal={type:'final'};return}do{g.slot++;if(g.slot>=g.schedule.length){g.slot=0;g.round++}}while(g.players[g.schedule[g.slot].team].eliminated||g.players[g.schedule[g.slot].team].finished);setFromSlot()};
ordered=function(final=false){const a=state.game.players.map((p,i)=>({...p,i}));if(final&&state.teams&&state.bestOf3)a.sort((x,y)=>(y.wins||0)-(x.wins||0)||(y.total||0)-(x.total||0)||y.score-x.score);else if(final||state.sort==='score')a.sort((x,y)=>y.score-x.score||x.i-y.i);else if(state.sort==='alpha')a.sort((x,y)=>x.name.localeCompare(y.name,'fr'));return a};
function reachedTarget(p){const g=state.game;if(g.continueMode&&!(state.teams&&state.bestOf3)){p.finished=true;advance();return}if(state.teams&&state.bestOf3){g.players.forEach(x=>x.total=(x.total||0)+x.score);p.wins++;if(p.wins>=2){p.finished=true;state.modal={type:'winner',name:p.name};return}state.modal={type:'round',name:p.name};return}state.modal={type:'winner',name:p.name}}
commitThrow=function(){const g=state.game,p=g.players[g.current],points=g.pending||0;if(g.correction){const a=g.actions[g.correction.index];p.score=a.before.score;p.misses=a.before.misses;p.eliminated=a.before.eliminated;p.finished=a.before.finished;p.throws.pop();applyResult(p,points,a.round);a.points=points;g.slot=g.correction.resumeSlot;g.round=g.correction.resumeRound;g.correction=null;g.pending=null;setFromSlot();if(p.score===state.target)reachedTarget(p);render();return}const before={score:p.score,misses:p.misses,eliminated:p.eliminated,finished:p.finished};applyResult(p,points,g.round);g.actions.push({player:g.current,member:g.currentMember,slot:g.slot,round:g.round,points,before});g.pending=null;if(p.score===state.target){reachedTarget(p);render();return}advance();render()};
beginCorrection=function(){const g=state.game,a=g.actions.at(-1);if(!a)return;g.correction={index:g.actions.length-1,resumeSlot:g.slot,resumeRound:g.round};g.slot=a.slot;g.round=a.round;g.pending=a.points||null;setFromSlot();render()};
cancelCorrection=function(){const g=state.game,c=g.correction;if(!c)return;g.slot=c.resumeSlot;g.round=c.resumeRound;g.pending=null;g.correction=null;setFromSlot();render()};
const oldModalView=modalView;modalView=function(){if(state.modal?.type==='round')return `<div class="overlay"><section class="sheet winner"><div class="trophy-big">🏆</div><h2>${esc(state.modal.name)} remporte la manche ${state.game.matchRound}</h2><button class="btn orange" id="continue">Manche suivante</button><button class="btn ghost" id="finish">Voir le classement final</button></section></div>`;return oldModalView()};
continueAfterWin=function(){const g=state.game,m=state.modal;if(m.type==='round'){g.matchRound++;let starter=(g.current+1)%g.players.length;if(g.matchRound===3)starter=g.players.map((p,i)=>({i,total:p.total||0})).sort((a,b)=>b.total-a.total)[0].i;g.players.forEach(p=>{p.score=0;p.misses=0;p.eliminated=false;p.finished=false;p.throws=[]});g.schedule=makeSchedule(g.players,starter);g.slot=0;g.round=1;g.actions=[];g.pending=null;state.modal=null;setFromSlot();render();return}const p=g.players.find(p=>p.name===m.name);p.finished=true;g.continueMode=true;state.modal=null;advance();render()};
const baseProfileView=profileView;profileView=function(){return baseProfileView().replaceAll('Manche','Tour').replaceAll('manche','tour')};
const COLOR_NAMES=['Vert','Bleu','Orange','Violet','Rouge','Turquoise'];
setupView=function(){const known=[...state.savedNames].sort((a,b)=>state.knownRecent?(b.used||0)-(a.used||0):a.name.localeCompare(b.name,'fr'));return `<section class="card setup-card"><div class="setup-heading"><h2>Qui joue ?</h2><div class="setup-icons"><button id="showPlacement" aria-label="Placement des quilles"><img src="icon-192.png" alt=""></button><button id="showSettings" aria-label="Paramètres">⚙</button></div></div><div class="count-buttons">${Array.from({length:17},(_,i)=>i+2).map(n=>`<button data-count="${n}" class="${state.players.length===n?'active':''}">${n}</button>`).join('')}</div><label class="row team-box"><input id="teams" type="checkbox" ${state.teams?'checked':''}><strong>Jouer en équipes</strong>${state.teams?'<button id="randomTeams" class="random-team" type="button" title="Répartir aléatoirement">⤨</button>':''}</label>${state.teams?`<div class="team-count-line"><label>Couleurs utilisées</label><select id="teamCount">${[2,3,4,5,6].map(n=>`<option ${state.teamCount===n?'selected':''}>${n}</option>`).join('')}</select>${state.teamCount===2?`<label class="best-three"><input id="bestOf3" type="checkbox" ${state.bestOf3?'checked':''}> 2 manches gagnantes</label>`:''}</div>`:''}<div class="name-grid ${state.teams?'with-teams':''}">${state.players.map((p,i)=>`<div class="name-team"><input data-player="${i}" value="${esc(p)}" placeholder="Joueur ${i+1}">${state.teams?`<select data-team="${i}" style="color:${COLORS[state.teamAssignments[i]??i%state.teamCount]}">${Array.from({length:state.teamCount},(_,t)=>`<option value="${t}" style="color:${COLORS[t]}" ${state.teamAssignments[i]===t?'selected':''}>${COLOR_NAMES[t]}</option>`).join('')}</select>`:''}</div>`).join('')}</div>${known.length?`<div class="known-head"><strong>Joueurs connus</strong><div class="mini-tools"><button id="knownSort">${state.knownRecent?'Récent':'A–Z'}</button><button id="knownDelete" class="${state.knownDelete?'active':''}">🗑</button></div></div><div class="known-list">${known.map(n=>`<button data-known="${esc(n.name)}" class="${state.players.includes(n.name)?'used':''}">${state.knownDelete?'× ':''}${esc(n.name)}</button>`).join('')}</div>`:''}<div class="segments">${[['entry','Saisie'],['alpha','A–Z'],['random','Aléatoire']].map(([v,l])=>`<button data-order="${v}" class="${state.order===v?'active':''}">${l}</button>`).join('')}</div><div id="error"></div><button class="btn orange validate" id="start">COMMENCER LA PARTIE</button></section>`};
const modalBeforeSettings=modalView;modalView=function(){if(state.modal?.type==='placement')return `<div class="overlay dismiss-modal"><section class="sheet image-sheet"><header><h2>Placement des quilles</h2><button class="icon-btn close-modal">×</button></header><img src="placement-quilles.png" alt="Placement initial des quilles"></section></div>`;if(state.modal?.type==='settings')return `<div class="overlay"><section class="sheet settings-sheet"><h2>Paramètres</h2><div class="field"><label>Éliminations</label><select id="settingsEliminations"><option value="yes" ${state.settingsDraft.eliminations?'selected':''}>Oui</option><option value="no" ${!state.settingsDraft.eliminations?'selected':''}>Non · retour à 0</option></select></div><div class="field"><label>Score à atteindre</label><select id="settingsTarget">${[50,75,100,125,150,175,200].map(v=>`<option ${state.settingsDraft.target===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="settings-actions"><button class="btn ghost" id="cancelSettings">Annuler</button><button class="btn orange" id="saveSettings">Valider</button></div></section></div>`;return modalBeforeSettings()};
const bindBeforeHome=bind;bind=function(){bindBeforeHome();document.querySelector('#showPlacement')?.addEventListener('click',()=>{state.modal={type:'placement'};render()});document.querySelector('#showSettings')?.addEventListener('click',()=>{state.settingsDraft={eliminations:state.eliminations,target:state.target};state.modal={type:'settings'};render()});document.querySelector('.close-modal')?.addEventListener('click',()=>{state.modal=null;render()});document.querySelector('.dismiss-modal')?.addEventListener('click',e=>{if(e.target===e.currentTarget){state.modal=null;render()}});document.querySelector('#cancelSettings')?.addEventListener('click',()=>{state.modal=null;delete state.settingsDraft;render()});document.querySelector('#saveSettings')?.addEventListener('click',()=>{state.eliminations=document.querySelector('#settingsEliminations').value==='yes';state.target=+document.querySelector('#settingsTarget').value;state.modal=null;delete state.settingsDraft;render()});document.querySelector('#randomTeams')?.addEventListener('click',()=>{const pool=state.players.map((_,i)=>i).sort(()=>Math.random()-.5);state.teamAssignments=state.players.map(()=>0);pool.forEach((player,pos)=>state.teamAssignments[player]=pos%state.teamCount);render()})};
const startGameBeforeColorNames=startGame;startGame=function(){startGameBeforeColorNames();if(state.screen==='game'&&state.teams){state.game.players.forEach((p,i)=>p.name=`Équipe ${i+1}`);render()}};
const bindBeforeColorRefresh=bind;bind=function(){bindBeforeColorRefresh();document.querySelectorAll('[data-team]').forEach(s=>s.onchange=e=>{state.teamAssignments[+e.target.dataset.team]=+e.target.value;render()})};
if(!state.knownSortInitialized){state.knownRecent=true;state.knownSortInitialized=true}
const STRONG_COLORS=['#ffd43b','#3b82f6','#f97316','#a855f7','#ef4444','#ffffff'];
setupView=function(){const known=[...state.savedNames].sort((a,b)=>state.knownRecent?(b.used||0)-(a.used||0):a.name.localeCompare(b.name,'fr'));return `<section class="card setup-card"><div class="setup-heading"><h2>Qui joue ?</h2><div class="setup-icons"><button id="showPlacement"><img src="icon-192.png" alt="Placement"></button><button id="showSettings">⚙</button></div></div><div class="count-buttons">${Array.from({length:17},(_,i)=>i+2).map(n=>`<button data-count="${n}" class="${state.players.length===n?'active':''}">${n}</button>`).join('')}</div><div class="name-grid ${state.teams?'with-teams':''}">${state.players.map((p,i)=>`<div class="name-team"><input data-player="${i}" value="${esc(p)}" placeholder="Joueur ${i+1}">${state.teams?`<button class="color-pick" data-cycle-team="${i}" style="background:${STRONG_COLORS[state.teamAssignments[i]??i%state.teamCount]}" aria-label="Changer la couleur d’équipe"></button>`:''}</div>`).join('')}</div>${known.length?`<div class="known-head"><strong>Joueurs connus</strong><div class="mini-tools"><button id="knownSort" title="${state.knownRecent?'Tri récent':'Tri alphabétique'}">${state.knownRecent?'◷':'AZ'}</button><button id="knownDelete" class="${state.knownDelete?'active':''}">🗑</button></div></div><div class="known-list">${known.map(n=>`<button data-known="${esc(n.name)}" class="${state.players.includes(n.name)?'used':''}">${state.knownDelete?'× ':''}${esc(n.name)}</button>`).join('')}</div>`:''}<div class="segments">${[['entry','Saisie'],['alpha','A–Z'],['random','Aléatoire']].map(([v,l])=>`<button data-order="${v}" class="${state.order===v?'active':''}">${l}</button>`).join('')}</div><label class="row team-box"><input id="teams" type="checkbox" ${state.teams?'checked':''}><strong>Jouer en équipes</strong>${state.teams?'<button id="randomTeams" class="random-team">⤨</button>':''}</label>${state.teams?`<div class="team-count-line"><label>Nombre d’équipes</label><select id="teamCount">${[2,3,4,5,6].map(n=>`<option ${state.teamCount===n?'selected':''}>${n}</option>`).join('')}</select>${state.teamCount===2?`<label class="best-three"><input id="bestOf3" type="checkbox" ${state.bestOf3?'checked':''}> 2 manches gagnantes</label>`:''}</div>`:''}<div id="error"></div><button class="btn orange validate" id="start">COMMENCER LA PARTIE</button></section>`};
function memberOrder(teamIndex,memberIndex){const x=state.game.schedule.findIndex(s=>s.team===teamIndex&&s.member===memberIndex);return x+1}
rankingRows=function(final){const list=ordered(final),podium=final||state.game.players.some(p=>p.finished);return list.map((p,rank)=>`<button style="background:${p.color||''}" class="player-row ${p.i===state.game.current&&!final?'current':''} ${p.eliminated?'eliminated':''} ${p.finished?'finished':''}" data-profile="${p.i}"><span class="turn-rank">${p.i+1}</span><span class="trophy-slot">${podium?trophy(rank):''}</span><strong class="row-name">${p.members?p.members.map((m,j)=>`<span class="team-member"><em>${memberOrder(p.i,j)}</em>${esc(m)}</span>`).join(''):esc(p.name)}</strong><strong>${p.score} pts${p.wins?` · ${p.wins} M`:''}</strong><span class="row-misses">${missIcons(p.misses)}</span></button>`).join('')};
const profileBeforeMembers=profileView;profileView=function(){const p=state.game.players[state.profile];if(!p.members)return profileBeforeMembers();const teamStats=stats(p);return `<div class="overlay profile-overlay"><section class="sheet"><header><div><small>FICHE DE L’ÉQUIPE</small><h2>Équipe ${p.i+1||state.profile+1}</h2></div><button class="icon-btn close-profile">×</button></header><div class="stat-grid"><div class="stat"><span>Score</span><b>${p.score}</b></div><div class="stat"><span>Moyenne</span><b>${teamStats.avg}</b></div><div class="stat"><span>Échecs</span><b>${teamStats.fails}</b></div><div class="stat"><span>Lancers</span><b>${p.throws.length}</b></div></div><h3>Joueurs</h3>${p.members.map(name=>{const ts=p.throws.filter(t=>t.member===name),ok=ts.filter(t=>t.points>0),avg=ok.length?(ok.reduce((a,t)=>a+t.points,0)/ok.length).toFixed(1):'—';return `<div class="member-stat"><strong>${esc(name)}</strong><span>${ts.length} lancers</span><span>moy. ${avg}</span><span>${ts.filter(t=>!t.points).length} échec(s)</span></div>`}).join('')}<h3>Historique de l’équipe</h3><ol class="throws">${p.throws.map(t=>`<li><span>${esc(t.member||'')}</span><b>${t.points||0}</b><span>${t.after} pts</span></li>`).join('')}</ol></section></div>`};
const applyBeforeMember=applyResult;applyResult=function(p,points,round){const out=applyBeforeMember(p,points,round),g=state.game;if(p.members&&p.throws.length)p.throws.at(-1).member=p.members[g.currentMember];return out};
beginCorrection=function(){const g=state.game;if(!g.actions.length)return;if(!g.correction)g.correction={index:g.actions.length-1,resumeSlot:g.slot,resumeRound:g.round};else g.correction.index=Math.max(0,g.correction.index-1);const a=g.actions[g.correction.index];g.slot=a.slot;g.round=a.round;g.pending=a.points||null;setFromSlot();render()};
cancelCorrection=function(){const g=state.game,c=g.correction;if(!c)return;if(c.index<g.actions.length-1){c.index++;const a=g.actions[c.index];g.slot=a.slot;g.round=a.round;g.pending=a.points||null;setFromSlot();render();return}g.slot=c.resumeSlot;g.round=c.resumeRound;g.pending=null;g.correction=null;setFromSlot();render()};
const gameBeforeHistory=gameView;gameView=function(){return gameBeforeHistory().replace(`id="undo" disabled`,`id="undo"`).replace(`id="undo"  aria`,`id="undo" aria`)};
const bindBeforeColorButtons=bind;bind=function(){bindBeforeColorButtons();document.querySelectorAll('[data-cycle-team]').forEach(b=>b.onclick=()=>{const i=+b.dataset.cycleTeam;state.teamAssignments[i]=((state.teamAssignments[i]??i%state.teamCount)+1)%state.teamCount;render()})};
const startBeforeStrongColors=startGame;startGame=function(){startBeforeStrongColors();if(state.screen==='game'&&state.teams){state.game.players.forEach((p,i)=>p.color=STRONG_COLORS[i]);render()}};
function replayActions(){const g=state.game;g.players.forEach(p=>{p.score=0;p.misses=0;p.eliminated=false;p.finished=false;p.throws=[]});g.actions.forEach(a=>{const p=g.players[a.player];a.before={score:p.score,misses:p.misses,eliminated:p.eliminated,finished:p.finished};const oldMember=g.currentMember;g.currentMember=a.member||0;applyResult(p,a.points,a.round);g.currentMember=oldMember})}
const commitBeforeDeepHistory=commitThrow;commitThrow=function(){const g=state.game;if(!g.correction){commitBeforeDeepHistory();return}const c=g.correction,a=g.actions[c.index];a.points=g.pending||0;replayActions();g.slot=c.resumeSlot;g.round=c.resumeRound;g.pending=null;g.correction=null;setFromSlot();render()};
function initTeamRound(starter=0){const g=state.game;g.teamOrders=g.players.map(()=>[]);g.teamUsed=g.players.map(p=>p.members.map(()=>false));g.teamCycle=g.players.map(()=>0);g.completedCycles=g.players.map(()=>0);g.current=starter;g.currentMember=null;g.awaitingMember=true;g.teamThrowCount=0;g.round=1;if(g.players[starter].members.length===1){g.teamOrders[starter].push(0);g.currentMember=0;g.awaitingMember=false}}
const startBeforeDynamicTeams=startGame;startGame=function(){startBeforeDynamicTeams();if(state.screen==='game'&&state.teams){initTeamRound(0);render()}};
function chooseMember(i){const g=state.game,p=g.players[g.current];if(g.teamOrders[g.current].includes(i))return;g.teamOrders[g.current].push(i);g.currentMember=i;g.awaitingMember=false;render()}
function nextTeamTurn(){const g=state.game;let n=g.current;do{n=(n+1)%g.players.length}while(g.players[n].eliminated||g.players[n].finished);g.current=n;g.teamThrowCount++;const p=g.players[n],order=g.teamOrders[n];if(order.length<p.members.length){g.currentMember=null;g.awaitingMember=true}else{g.currentMember=order[g.teamCycle[n]%order.length];g.awaitingMember=false}}
function teamChooseView(){const g=state.game,p=g.players[g.current],remaining=p.members.map((name,i)=>({name,i})).filter(x=>!g.teamOrders[g.current].includes(x.i));return `<section class="hero team-picker"><small>TOUR ${g.round} · ${esc(p.name)}</small><h1>Qui lance ?</h1><div class="member-buttons">${remaining.map(x=>`<button data-choose-member="${x.i}">${esc(x.name)}</button>`).join('')}</div></section><div class="ranking-title"><h3>👥</h3><div class="sort-radios"><button data-sort="turn" class="${state.sort==='turn'?'active':''}">↻</button><button data-sort="alpha" class="${state.sort==='alpha'?'active':''}">AZ</button><button data-sort="score" class="${state.sort==='score'?'active':''}">🏆</button></div></div>${rankingRows(false)}`}
const gameBeforePicker=gameView;gameView=function(){if(state.teams&&state.game.awaitingMember)return teamChooseView();return gameBeforePicker()};
rankingRows=function(final){const list=ordered(final),podium=final||state.game.players.some(p=>p.finished),g=state.game;return list.map((p,rank)=>`<button style="background:${p.color||''}" class="player-row ${p.i===g.current&&!final?'current':''} ${p.eliminated?'eliminated':''} ${p.finished?'finished':''}" data-profile="${p.i}"><span class="turn-rank">${p.i+1}</span><span class="trophy-slot">${podium?trophy(rank):''}</span><strong class="row-name">${p.members?p.members.map((m,j)=>`<span class="team-member">${esc(m)}${g.teamUsed?.[p.i]?.[j]?'<i>✓</i>':''}</span>`).join(''):esc(p.name)}</strong><strong>${p.score} pts${p.wins?` · ${p.wins} manche${p.wins>1?'s':''}`:''}</strong><span class="row-misses">${missIcons(p.misses)}</span></button>`).join('')};
function awardEliminationWin(){const g=state.game,alive=g.players.filter(p=>!p.eliminated&&!p.finished);if(g.players.length===2&&alive.length===1){reachedTarget(alive[0]);return true}return false}
const commitBeforeTeamAlternation=commitThrow;commitThrow=function(){const g=state.game;if(!state.teams||g.correction){commitBeforeTeamAlternation();return}const p=g.players[g.current],member=g.currentMember,points=g.pending||0,before={score:p.score,misses:p.misses,eliminated:p.eliminated,finished:p.finished};applyResult(p,points,g.round);p.throws.at(-1).member=p.members[member];g.actions.push({player:g.current,member,round:g.round,points,before});g.pending=null;g.teamUsed[g.current][member]=true;const order=g.teamOrders[g.current];if(order.length===p.members.length){g.teamCycle[g.current]++;if(g.teamCycle[g.current]%order.length===0)g.teamUsed[g.current].fill(false)}if(p.score===state.target){reachedTarget(p);render();return}if(p.eliminated&&awardEliminationWin()){render();return}nextTeamTurn();render()};
beginCorrection=function(){const g=state.game;if(!g.actions.length)return;if(!g.correction)g.correction={index:g.actions.length-1,resumeTeam:g.current,resumeMember:g.currentMember,resumeRound:g.round,resumeAwaiting:g.awaitingMember};else g.correction.index=Math.max(0,g.correction.index-1);const a=g.actions[g.correction.index];g.current=a.player;g.currentMember=a.member||0;g.round=a.round;g.pending=a.points||null;g.awaitingMember=false;render()};
cancelCorrection=function(){const g=state.game,c=g.correction;if(!c)return;if(c.index<g.actions.length-1){c.index++;const a=g.actions[c.index];g.current=a.player;g.currentMember=a.member||0;g.round=a.round;g.pending=a.points||null;render();return}g.current=c.resumeTeam;g.currentMember=c.resumeMember;g.round=c.resumeRound;g.awaitingMember=c.resumeAwaiting;g.pending=null;g.correction=null;render()};
continueAfterWin=function(){const g=state.game,m=state.modal;if(m.type==='round'){g.matchRound++;let starter=(g.current+1)%g.players.length;if(g.matchRound===3)starter=g.players.map((p,i)=>({i,total:p.total||0})).sort((a,b)=>b.total-a.total)[0].i;g.players.forEach(p=>{p.score=0;p.misses=0;p.eliminated=false;p.finished=false;p.throws=[]});g.actions=[];g.pending=null;state.modal=null;initTeamRound(starter);render();return}const p=g.players.find(p=>p.name===m.name);p.finished=true;g.continueMode=true;state.modal=null;state.teams?nextTeamTurn():advance();render()};
function globalStats(){const people=[];state.game.players.forEach(p=>{if(p.members)p.members.forEach(name=>{const ts=p.throws.filter(t=>t.member===name),ok=ts.filter(t=>t.points>0);people.push({name,fails:ts.filter(t=>!t.points).length,avg:ok.length?ok.reduce((a,t)=>a+t.points,0)/ok.length:0,best:ok.length?Math.max(...ok.map(t=>t.points)):0,throws:ts.length})});else{const ok=p.throws.filter(t=>t.points>0);people.push({name:p.name,fails:p.throws.filter(t=>!t.points).length,avg:ok.length?ok.reduce((a,t)=>a+t.points,0)/ok.length:0,best:ok.length?Math.max(...ok.map(t=>t.points)):0,throws:p.throws.length})}});const max=(key)=>[...people].sort((a,b)=>b[key]-a[key])[0];return{fails:max('fails'),avg:max('avg'),best:max('best'),throws:max('throws')}}
function finalPanel(withStats=false){return `<div class="overlay"><section class="sheet final-sheet"><div class="final-heading"><h2>Partie terminée</h2><button id="globalStats">Statistiques</button></div>${rankingRows(true)}<div class="final-actions"><button class="btn ghost" id="cancelFinal">Annuler</button><button class="btn orange" id="newgame">Nouvelle partie</button></div></section>${withStats?statsPanel():''}</div>`}
